#!/usr/bin/env node
/**
 * Fails when the hand-written preview stub in frontend/preview-stub/ has fallen behind the Go
 * bound-method surface it mirrors.
 *
 * Why this exists: frontend/wailsjs/ is normally generated by `wails dev`/`wails build`, which needs
 * to compile the Go backend -- impossible on a machine without Hikvision's proprietary SDK vendored
 * (macOS). preview-stub/ is the hand-written stand-in, installed into wailsjs/ by
 * `npm run stub:install`. Being hand-written, it drifts silently every time a bound method is added:
 * Vite does not type-check, so `npm run dev` still starts and the affected page only fails when
 * opened, on an undefined import. The sibling tarozi-post-app repo let exactly that happen for six
 * days across 23 bound methods before anyone noticed, which is why this guard exists here from the
 * start rather than after the same lesson.
 *
 * This compares *names* only. Signatures and return shapes are the type-checker's job (`npm run
 * build` runs tsc), and tsc can only do that job if the export exists at all.
 *
 * Severity is deliberately conditional. Drift is only an actual problem when the stub is the thing
 * being run, so it is an error when wailsjs/ currently holds the stub (or when --strict is passed,
 * as `npm run check:stub` does) and a warning otherwise. A production `wails build` on Windows uses
 * real generated bindings and must never fail over a macOS-only preview convenience.
 */
import {readFileSync, readdirSync, existsSync} from 'node:fs';
import {join, dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const frontendDir = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = resolve(frontendDir, '..');
const stubPath = join(frontendDir, 'preview-stub', 'go', 'main', 'App.ts');
const installedPath = join(frontendDir, 'wailsjs', 'go', 'main', 'App.ts');

const STUB_MARKER = 'FRONTEND-ONLY PREVIEW STUB';
const strict =
  process.argv.includes('--strict') ||
  (existsSync(installedPath) && readFileSync(installedPath, 'utf8').includes(STUB_MARKER));

const fail = (msg) => {
  if (strict) {
    console.error(msg);
    process.exit(1);
  }
  console.warn(msg);
  process.exit(0);
};

if (!existsSync(stubPath)) {
  fail('check-stub-drift: frontend/preview-stub/go/main/App.ts not found.');
}

const stubSource = readFileSync(stubPath, 'utf8');

// Bound methods are exported methods on *App across the root package's .go files.
const boundMethods = new Set();
for (const entry of readdirSync(repoRoot)) {
  if (!entry.endsWith('.go') || entry.endsWith('_test.go')) continue;
  const src = readFileSync(join(repoRoot, entry), 'utf8');
  for (const m of src.matchAll(/^func \(a \*App\) ([A-Z]\w*)\s*\(/gm)) {
    boundMethods.add(m[1]);
  }
}

if (boundMethods.size === 0) {
  console.error('check-stub-drift: found no `func (a *App) Xxx(` declarations - has the binding layout moved?');
  process.exit(1);
}

const stubbed = new Set(
  [...stubSource.matchAll(/^export (?:function|const) ([A-Za-z]\w*)/gm)].map((m) => m[1]),
);

const missing = [...boundMethods].filter((name) => !stubbed.has(name)).sort();
const extra = [...stubbed].filter((name) => !boundMethods.has(name)).sort();

if (missing.length === 0 && extra.length === 0) {
  console.log(`check-stub-drift: OK - preview stub covers all ${boundMethods.size} bound methods.`);
  process.exit(0);
}

const lines = ['check-stub-drift: the preview stub no longer matches the Go bound-method surface.', ''];
if (missing.length) {
  lines.push(`  Missing from the stub (${missing.length}) - these will be undefined at runtime in \`npm run dev\`:`);
  for (const n of missing) lines.push(`    - ${n}`);
}
if (extra.length) {
  if (missing.length) lines.push('');
  lines.push(`  Exported by the stub but no longer bound in Go (${extra.length}) - probably renamed or removed:`);
  for (const n of extra) lines.push(`    - ${n}`);
}
lines.push('');
lines.push('Update frontend/preview-stub/go/main/App.ts (and go/models.ts if new DTOs cross the boundary),');
lines.push('then re-run `npm run stub:install`. See frontend/preview-stub/README.md.');

fail(lines.join('\n'));
